-- calc_clients_count_of_big_invoices
-- Field: Clients.CountOfBigInvoices
-- Type: aggregation | DataType: integer | Returns: INTEGER

CREATE OR REPLACE FUNCTION calc_clients_count_of_big_invoices(p_client_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM invoices WHERE client = (SELECT NULLIF(client_id, '') FROM clients WHERE client_id = p_client_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_clients_average_order_value
-- Field: Clients.AverageOrderValue
-- Type: aggregation | DataType: number | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_clients_average_order_value(p_client_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(AVG((calc_invoices_invoice_total(invoice_id))::numeric), 0) FROM invoices WHERE client = p_client_id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_clients_is_vip
-- Field: Clients.IsVIP
-- Type: calculated | DataType: boolean | Returns: BOOLEAN

CREATE OR REPLACE FUNCTION calc_clients_is_vip(p_client_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN ((calc_clients_average_order_value(p_client_id))::NUMERIC > 500 AND calc_clients_has_recent_invoices(p_client_id)) THEN TRUE ELSE FALSE END)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_clients_has_recent_invoices
-- Field: Clients.HasRecentInvoices
-- Type: calculated | DataType: boolean | Returns: BOOLEAN

CREATE OR REPLACE FUNCTION calc_clients_has_recent_invoices(p_client_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT /* WARNING: Formula translation failed: DATEADD() unit 'days' is not a valid interval unit (expected: second, minute, hour, day, week, month, year)
   Original Airtable formula:
   =IF({{LastInvoice}} > DATEADD(TODAY(), -220, 'days'), TRUE(), FALSE())
*/
NULL::boolean;
$$ LANGUAGE sql STABLE;

-- calc_clients_last_invoice
-- Field: Clients.LastInvoice
-- Type: aggregation | DataType: datetime | Returns: TIMESTAMPTZ

CREATE OR REPLACE FUNCTION calc_clients_last_invoice(p_client_id TEXT)
RETURNS TIMESTAMPTZ AS $$
  SELECT ((SELECT COALESCE(SUM((order_date)::numeric), 0) FROM invoices WHERE client = p_client_id))::timestamptz;
$$ LANGUAGE sql STABLE;

-- calc_clients_customer_since_days
-- Field: Clients.CustomerSinceDays
-- Type: calculated | DataType: integer | Returns: INTEGER

CREATE OR REPLACE FUNCTION calc_clients_customer_since_days(p_client_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (SELECT created_at::timestamptz FROM clients WHERE client_id = p_client_id) IS NOT NULL THEN ((CURRENT_TIMESTAMP::date - (SELECT created_at::timestamptz FROM clients WHERE client_id = p_client_id)::date))::text ELSE (NULL)::text END)::integer;
$$ LANGUAGE sql STABLE;

