-- calc_products_name
-- Field: Products.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_products_name(p_product_id TEXT)
RETURNS TEXT AS $$
  SELECT (LOWER(REPLACE((SELECT NULLIF(sku, '') FROM products WHERE product_id = p_product_id), ' ', '-')))::text;
$$ LANGUAGE sql STABLE;

-- calc_products_profit
-- Field: Products.Profit
-- Type: calculated | DataType: number | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_products_profit(p_product_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT unit_price FROM products WHERE product_id = p_product_id)) AS v) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT cost FROM products WHERE product_id = p_product_id)) AS v) __safe_numeric), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_products_margin
-- Field: Products.Margin
-- Type: calculated | DataType: number | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_products_margin(p_product_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE(1, 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT cost FROM products WHERE product_id = p_product_id)) AS v) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT unit_price FROM products WHERE product_id = p_product_id)) AS v) __safe_numeric), 0), 0))) AS v) __safe_numeric), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_products_is_high_margin
-- Field: Products.IsHighMargin
-- Type: calculated | DataType: boolean | Returns: BOOLEAN

CREATE OR REPLACE FUNCTION calc_products_is_high_margin(p_product_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_products_margin(p_product_id))::NUMERIC > 0.65)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_products_stock_quantity
-- Field: Products.StockQuantity
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_products_stock_quantity(p_product_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((quantity)::numeric), 0) FROM inventory_adjustments WHERE product = p_product_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_products_cogs
-- Field: Products.COGS
-- Type: calculated | DataType: number | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_products_cogs(p_product_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_products_stock_quantity(p_product_id)) AS v) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT cost FROM products WHERE product_id = p_product_id)) AS v) __safe_numeric), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_products_count_of_vip_orders
-- Field: Products.CountOfVIPOrders
-- Type: aggregation | DataType: integer | Returns: INTEGER

CREATE OR REPLACE FUNCTION calc_products_count_of_vip_orders(p_product_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COUNT(*) FROM invoice_line_items WHERE product = (SELECT NULLIF(product_id, '') FROM products WHERE product_id = p_product_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_products_has_been_ordered_by_vip_customers
-- Field: Products.HasBeenOrderedByVIPCustomers
-- Type: calculated | DataType: boolean | Returns: BOOLEAN

CREATE OR REPLACE FUNCTION calc_products_has_been_ordered_by_vip_customers(p_product_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN ((calc_products_count_of_vip_orders(p_product_id))::NUMERIC > 0 AND (calc_products_stock_quantity(p_product_id))::NUMERIC > 250) THEN TRUE ELSE FALSE END)::boolean;
$$ LANGUAGE sql STABLE;

