-- calc_invoices_total_quantity
-- Field: Invoices.TotalQuantity
-- Type: aggregation | DataType: integer | Returns: INTEGER

CREATE OR REPLACE FUNCTION calc_invoices_total_quantity(p_invoice_id TEXT)
RETURNS INTEGER AS $$
