$$ LANGUAGE sql STABLE;

-- calc_invoices_sub_total
-- Field: Invoices.SubTotal
-- Type: aggregation | DataType: number | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_invoices_sub_total(p_invoice_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((calc_invoice_line_items_sub_total(invoice_line_item_id))::numeric), 0) FROM invoice_line_items WHERE invoice = p_invoice_id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_invoices_is_big_order
-- Field: Invoices.IsBigOrder
-- Type: calculated | DataType: boolean | Returns: BOOLEAN

CREATE OR REPLACE FUNCTION calc_invoices_is_big_order(p_invoice_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_invoices_sub_total(p_invoice_id))::NUMERIC > 350)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_invoices_tax_amount
-- Field: Invoices.TaxAmount
-- Type: calculated | DataType: number | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_invoices_tax_amount(p_invoice_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_invoices_sub_total(p_invoice_id)) AS v) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_invoices_tax_rate(p_invoice_id)) AS v) __safe_numeric), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_invoices_invoice_total
-- Field: Invoices.InvoiceTotal
-- Type: calculated | DataType: number | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_invoices_invoice_total(p_invoice_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_invoices_sub_total(p_invoice_id)) AS v) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_invoices_tax_amount(p_invoice_id)) AS v) __safe_numeric), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_invoices_total_paid
-- Field: Invoices.TotalPaid
-- Type: aggregation | DataType: number | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_invoices_total_paid(p_invoice_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((calc_payments_completed_amount(payment_id))::numeric), 0) FROM payments WHERE invoice = p_invoice_id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_invoices_amount_due
-- Field: Invoices.AmountDue
-- Type: calculated | DataType: number | Returns: NUMERIC

CREATE OR REPLACE FUNCTION calc_invoices_amount_due(p_invoice_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (ROUND(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_invoices_invoice_total(p_invoice_id)) AS v) __safe_numeric), 0) - COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_invoices_total_paid(p_invoice_id)) AS v) __safe_numeric), 0)))::NUMERIC, (2)::INTEGER))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_invoices_is_paid_in_full
-- Field: Invoices.IsPaidInFull
-- Type: calculated | DataType: boolean | Returns: BOOLEAN

CREATE OR REPLACE FUNCTION calc_invoices_is_paid_in_full(p_invoice_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN (calc_invoices_amount_due(p_invoice_id))::NUMERIC <= 0 THEN TRUE ELSE FALSE END)::boolean;
$$ LANGUAGE sql STABLE;

