-- ----------------------------------------------------------------------------
-- vw_states: Table: States
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_states CASCADE;
CREATE VIEW vw_states WITH (security_invoker = ON) AS
SELECT
  t.state_id,
  calc_states_name(t.state_id) AS name,
  t.code,
  t.text,
  t.tax_rate,
  calc_states_addresses(t.state_id) AS addresses
FROM states t;

-- ----------------------------------------------------------------------------
-- vw_types_of_addresses: Table: TypesOfAddresses
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_types_of_addresses CASCADE;
CREATE VIEW vw_types_of_addresses WITH (security_invoker = ON) AS
SELECT
  t.types_of_addresse_id,
  t.name,
  calc_types_of_addresses_addresses(t.types_of_addresse_id) AS addresses,
  t.is_shipping_address,
  t.is_billing_address
FROM types_of_addresses t;



